-- Sovietski: the SM-420 Road Hammer assault squad vehicle and the SM-451 Black Water amphibious APC (printed 187-189).
-- 2 vehicle rows, with 26 locations and 7 weapon entries.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~388-sovietski-v4.sql
--
-- Written by scripts/vessel-sql.mjs from 1 worker file(s). Every value
-- is printable ASCII, every row cites its book, and a Main Body location
-- agrees with its vehicle's mdc_main_body.

INSERT OR IGNORE INTO vehicles (slug, name, system, vehicle_class, crew, passengers, speed_ground, speed_air, speed_water, dimensions, weight_tons, mdc_main_body, is_mega_damage, ar, cost, cost_note, description, source_book) VALUES
  ('sm-420-road-hammer', 'SM-420 Road Hammer Assault Squad Vehicle', 'rifts', 'vehicle', 'One driver, a partial or full cyborg or a Light Machine, fitted with Cyberlink. Any full or partial cyborg with Cyberlink can take the wheel through a Cyber-Harness.', 'Four cyborg troops besides the driver, or six human-sized soldiers jammed in very tightly, which the book advises against. All ride in Cyber-Harnesses.', '90 mph (144 km) on roads, 50 mph (80 km) off-road. Range 500 miles (800 km) on one electric charge; unlimited for a nuclear one.', 'None.', 'Does not float or swim, but fords water up to 5 feet (1.5 m) deep.', 'Height 8 feet (2.4 m), width 8 feet (2.4 m), length 16 feet (4.9 m).', '5.6 tons fully loaded', 225, 1, NULL, 1700000, 'Black Market: 1.7 million credits fully loaded with an electric engine, fair availability; 3.4 million for the nuclear version, poor availability.', 'A compact four-wheeled armored car in the mold of a combat Humvee or the pre-Rifts Russian GAZ-2975: narrow enough for city streets and alleys, and with big M.D.C. tires on independent suspension it climbs over broken road, shallow craters and fallen trees. The engine sits at the back and the driver steers by Cyberlink from the middle of the cabin, so the nose has no windshield, only an armored viewing slit, and carries a heavy ram prow for shoving wreckage aside, breaking into enemy lines and bowling over infantry. Two passengers sit beside the driver and two ahead of him. On the roof: a main gun (a medium rail gun or a pulse laser), two fixed forward ion blasters the driver fires, a spotlight, a secondary sensor cluster and a hatch; three pop-up mini-missile tubes line each rear flank. The Sovietski Army and the police both use it for street and border patrol, scouting, rapid response, escort, S.W.A.T.-style raids, riot control and light troop or cargo hauling; usually a five-man S.W.A.T., commando or cyborg squad is issued one and dismounts to do the job. Two gunports on each side and one in front under the slit let riders fire handheld weapons, as Shooting Wild while moving. The spotlight turns 360 degrees and tilts 45 degrees up or down, reaching 600 feet (183 m). Cargo: a 4x4x7 foot (1.2 x 1.2 x 2.1 m) bay behind the driver for weapons, ammunition, gear or supplies. Power: an electric battery (60% of them) or nuclear (40%), 10-year average life. Has the standard Sovietski vehicle features.', 'Rifts World Book 36: Sovietski p.187-188'),
  ('sm-451-black-water', 'SM-451 Black Water Amphibious APC', 'rifts', 'vehicle', 'Three: a pilot, a communications officer and a gunner.', 'Up to 14 human-sized troops or Light Machines in the troop compartment, or 10 Heavy Machines, or five Superheavy Machines crammed in.', '90 mph (144 km) top, 60 mph (96 km) cruising. Range effectively unlimited.', 'None.', '40 mph (64 km) on the surface. Cannot submerge; can drive through water up to 5 feet (1.5 m) deep without switching to its water drive.', 'Height 18 feet (5.5 m), width 15 feet (4.6 m), length 33 feet (10.1 m).', '29 tons fully loaded', 400, 1, NULL, 35000000, 'Rare: the Sovietski sells it only to allies. 35 million credits new and undamaged; 20 million or more stripped of its weapons, when one can be found.', 'An eight-wheeled amphibious armored personnel carrier first built to guard the Volga River Hydroelectric Dam and since taken into general Army service. It covers rough country and dirt roads quickly enough to put troops where they are needed and back them up. At the water''s edge it simply drives in: the wheels pull up flush with the hull and a propeller and hydro-jet drive take over, slower than a true boat but serviceable. Two four-barrel roof turrets, one facing forward and one facing back, each have their own gunner (the communications officer usually works the front one); the pilot handles two pop-up mini-missile launchers and a pair of mini-torpedo tubes under the nose. Three gunports on each side let the troops fire out, as Shooting Wild while moving or in rough water. A few have gone to Sovietski allies, the NGR and the Romanov Camp, who prize it as both a troop carrier and a fighting vehicle. Cargo: three lockers, each with a rifle, a sidearm, a canteen, a suit of Red Star body armor and personal effects, plus 10 gallons (38 liters) of drinking water and a week of food for the crew; the 10x10x15 foot (3x3x4.6 m) troop bay can instead carry up to 34 tons of supplies. Nuclear, 15-year average life. Standard Sovietski vehicle sensors.', 'Rifts World Book 36: Sovietski p.188-189');

INSERT OR IGNORE INTO vehicle_locations (vehicle_slug, location, mdc, mdc_note, ordinal) VALUES
  ('sm-420-road-hammer', 'Roof Main Gun', 100, 'The rail gun or pulse laser.', 1),
  ('sm-420-road-hammer', 'Roof Ion Blasters (2)', 20, 'Each; forward roof. Small target: Called Shot only, -3 to strike.', 2),
  ('sm-420-road-hammer', 'Mini-Missile Launch Tubes (6)', 10, 'Each; rear sides. Small target: Called Shot only, -3 to strike.', 3),
  ('sm-420-road-hammer', 'Sensor Turret', 35, 'Rear. Small target: Called Shot only, -3 to strike. Destroying it cuts long-range communication and radar.', 4),
  ('sm-420-road-hammer', 'Secondary Sensor Turret', 20, 'Roof. Small target: Called Shot only, -3 to strike. With the main sensor turret also gone, all optical sensors and targeting are lost: the driver goes blind or on his passengers'' directions, -40% piloting and -5 to dodge.', 5),
  ('sm-420-road-hammer', 'Top Access Hatch', 55, 'Roof. Small target: Called Shot only, -3 to strike.', 6),
  ('sm-420-road-hammer', 'Spotlight', 10, 'Small, on the roof. Small target: Called Shot only, -3 to strike.', 7),
  ('sm-420-road-hammer', 'Headlights (4)', 3, 'Each. Small target: Called Shot only, -3 to strike.', 8),
  ('sm-420-road-hammer', 'Doors (4)', 100, 'Each.', 9),
  ('sm-420-road-hammer', 'Armored Window Slits (5)', 15, 'Each; one in front, two on each side. Small target: Called Shot only, -3 to strike.', 10),
  ('sm-420-road-hammer', 'Armored M.D.C. Tires (4)', 20, 'Each. Losing one: -50% speed, -20% piloting, -2 to dodge. Losing two or more: -75% speed, -50% piloting, -4 to dodge.', 11),
  ('sm-420-road-hammer', 'Rear Mini-Missile Launcher', 55, 'Listed this way in the location table; the weapon entries describe the six side tubes.', 12),
  ('sm-420-road-hammer', 'Ram Prow', 120, 'Front.', 13),
  ('sm-420-road-hammer', 'Reinforced Crew Compartment', 50, NULL, 14),
  ('sm-420-road-hammer', 'Main Body', 225, 'Depleting it shuts the vehicle down completely.', 15),
  ('sm-451-black-water', 'Front Rail Gun Turret', 100, NULL, 1),
  ('sm-451-black-water', 'Top Rail Gun Turret', 100, 'The rear-facing turret.', 2),
  ('sm-451-black-water', 'Mini-Missile Launchers (2)', 20, 'Each.', 3),
  ('sm-451-black-water', 'Torpedo Tubes (2)', 35, 'Each. Small target: Called Shot only, -3 to strike.', 4),
  ('sm-451-black-water', 'Sensor Turret', 35, 'Small target: Called Shot only, -3 to strike. Destroying it cuts long-range communication and every optical and sensory aid; the pilot loses the bonuses his piloting skill and the vehicle''s features give.', 5),
  ('sm-451-black-water', 'Top Access Hatch', 100, 'Small target: Called Shot only, -3 to strike.', 6),
  ('sm-451-black-water', 'Armored Wheels (8)', 80, 'Each. Losing one: -50% speed, -20% piloting, -2 to dodge. Losing two or more: -75% speed, -50% piloting, -4 to dodge.', 7),
  ('sm-451-black-water', 'Reinforced Crew Compartment', 130, NULL, 8),
  ('sm-451-black-water', 'Separate Reinforced Troop Compartment', 150, NULL, 9),
  ('sm-451-black-water', 'Rear Troop Deployment Door', 150, NULL, 10),
  ('sm-451-black-water', 'Main Body', 400, 'Depleting it shuts the vehicle down completely.', 11);

INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('sm-420-road-hammer', 1, 'S-500 Pulse Laser Roof Gun or Light Rail Gun', 'Pulse laser: 2D6 M.D. single shot, 6D6 M.D. triple pulse. Light rail gun: 1D4 M.D. per round, 5D6 M.D. per 20-round burst.', 1, '4,000 feet (1,219 m) for either weapon', 'Each pulse or burst uses one melee attack.', 'Rail gun: 1,200-round drum, 60 bursts. Laser on an electric Road Hammer: an E-Pack good for 60 pulses or 180 single shots, with a spare E-Pack in the crew compartment; a standard E-Clip fits in the side but gives only five pulses. Laser on a nuclear Road Hammer: unlimited.', NULL, 'One gun near the middle of the roof, built as either weapon. Fired remotely from inside or worked by a gunner standing in the roof hatch just behind it, usually when the vehicle is stuck or its sensors are out. Turns 240 degrees and elevates 60 degrees up and down. Assault, then defense.'),
  ('sm-420-road-hammer', 2, 'Forward Ion Blasters (2)', '3D6 M.D. single blast, 6D6 M.D. double blast', 1, '1,200 feet (366 m)', 'Each blast uses one of the gunner''s melee attacks.', 'Effectively unlimited.', NULL, 'Short-barreled ion guns on either side of the forward roof, fixed to fire ahead. The driver fires them, or a Cyberlinked passenger if the driver hands them over. Forward assault, then defense.'),
  ('sm-420-road-hammer', 3, 'Mini-Missile Launch Tubes (6)', 'Varies with the missile. Usual load: four armor piercing (1D4x10 M.D. to a 3 foot/0.9 m radius) or fragmentation (5D6 M.D. to a 20 foot/6.1 m radius), plus two smoke (a cloud of 20 foot/6.1 m radius). Sleep or tear gas missiles for riot work.', 1, 'One mile (1.6 km)', 'One at a time or volleys of 2, 4 or 6.', '12, two per tube.', NULL, 'Pop-up launchers, three on each side toward the rear, fired by the driver. Assault, then anti-armor.'),
  ('sm-420-road-hammer', 4, 'Ram Prow', '1D6 M.D. per 10 mph (16 km) of speed; a humanoid under 18 feet (5.5 m) tall has a 01-80% chance of being knocked down, losing initiative and one melee attack', 1, 'Contact: a ram.', NULL, NULL, NULL, 'Pushes stalled or wrecked cars and debris aside, breaks through light fortifications and knocks down infantry and Light or Heavy Machines. The prow itself takes 20% of the damage when it rams something big and heavy (a Superheavy Machine, a Warlord Shocktrooper, an armored vehicle, a giant robot, a Gargoyle, a wall or a fortification), and none from crowds, Light Machines, Brodkil, fences, barbed wire, cars or car-sized debris.'),
  ('sm-451-black-water', 1, 'Heavy Four-Barrel Rail Gun or Laser Turrets (2)', 'Rail gun: 1D4x10 M.D. per 20-round burst from two barrels, 2D4x10 M.D. from all four; bursts only, no single shots. Laser: 6D6 M.D. from two barrels, 1D6x10+6 M.D. from four.', 1, '4,000 feet (1,219 m) for either weapon', 'Each burst uses one melee attack (the book says the pilot''s).', 'Rail gun: 8,000-round internal magazine, 200 four-barrel bursts or 400 two-barrel bursts. Laser: effectively unlimited.', NULL, 'One turret toward the front of the roof facing forward, an identical one toward the back facing rearward, each with its own gunner, turning 360 degrees and elevating 60 degrees up and down. The two may be the same weapon or one of each. Laid down as covering fire when troops go in or come out, and for support and defense. Anti-personnel and anti-armor, then anti-aircraft and anti-missile.'),
  ('sm-451-black-water', 3, 'Mini-Missile Launchers (2)', 'Varies with the missile; usually high explosive (5D6 M.D. to a 5 foot/1.5 m radius) or fragmentation (5D6 M.D. to a 20 foot/6.1 m radius)', 1, 'Varies with the missile: one mile (1.6 km) for high explosive, half a mile (0.8 km) for fragmentation', 'One at a time or volleys of 2, 3 or 4.', '24, twelve per launcher.', NULL, 'Pop-up launchers, one on each side, fired by the pilot to knock down incoming missile volleys or to attack. The book numbers this weapon 3 and prints no weapon 2. Anti-personnel, then assault.'),
  ('sm-451-black-water', 4, 'Mini-Torpedo Launchers (2)', '1D6x10 M.D. per torpedo', 1, 'One mile (1.6 km)', 'One at a time or volleys of two.', '14, seven per tube.', NULL, 'Two tubes on the underside between the front wheels, fired by the pilot. Anti-ship, then anti-sea monster.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 2 machines are in' AS assertion, count(*) AS got, 2 AS want
  FROM vehicles WHERE slug IN ('sm-420-road-hammer', 'sm-451-black-water');
SELECT 'their 26 locations are in' AS assertion, count(*) AS got, 26 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('sm-420-road-hammer', 'sm-451-black-water');
SELECT 'their 7 weapon entries are in' AS assertion, count(*) AS got, 7 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('sm-420-road-hammer', 'sm-451-black-water');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('sm-420-road-hammer', 'sm-451-black-water') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

